'use strict';

const crypto = require('crypto');

/**
 * Generates a clean, URL-safe unique ID with an optional prefix.
 * @param {string} [prefix=''] - E.g. 'p_' for player, 'm_' for match
 * @returns {string}
 */
function generateId(prefix = '') {
  const randomPart = crypto.randomBytes(8).toString('hex');
  return prefix ? `${prefix}${randomPart}` : randomPart;
}

module.exports = {
  generateId
};
